mapper.select:

SELECT
    p.property_id AS propertyId,

    pi.image_url AS thumbnailUrl,

    p.property_type AS propertyType,
    p.transaction_type AS transactionType,

    p.price AS price,
    p.deposit AS deposit,
    p.monthly_rent AS monthlyRent,

    p.area_m2 AS areaM2,
    p.floor AS floor,
    p.maintenance_fee AS maintenanceFee,

    CONCAT(r.province, ' ', r.city, ' ', r.district) AS regionName

FROM property p
    LEFT JOIN region r
        ON p.region_id = r.region_id

    LEFT JOIN property_image pi
        ON p.property_id = pi.property_id
        AND pi.is_thumbnail = 1

    p.deleted_at IS NULL


        AND p.property_type = #{propertyType}


        AND p.transaction_type = #{transactionType}


        AND p.status = #{status}


        AND p.region_id = #{regionId}


        AND p.price >= #{minPrice}


        AND p.price <= #{maxPrice}


        AND p.deposit >= #{minDeposit}


        AND p.deposit <= #{maxDeposit}


        AND p.monthly_rent >= #{minMonthlyRent}


        AND p.monthly_rent <= #{maxMonthlyRent}


ORDER BY
    p.property_id DESC
LIMIT #{pageSize} OFFSET #{offset}

SELECT
    COUNT(*)
FROM property p

    deleted_at IS NULL

        AND p.property_type = #{propertyType}


        AND p.transaction_type = #{transactionType}


        AND p.status = #{status}


        AND p.region_id = #{regionId}



        AND p.price >= #{minPrice}


        AND p.price <= #{maxPrice}


        AND p.deposit >= #{minDeposit}


        AND p.deposit <= #{maxDeposit}


        AND p.monthly_rent >= #{minMonthlyRent}


        AND p.monthly_rent <= #{maxMonthlyRent}
